package com.falconenergy.entity;
import jakarta.persistence.*; import lombok.*; import org.hibernate.annotations.SQLDelete; import org.hibernate.annotations.SQLRestriction; import java.math.BigDecimal; import java.time.LocalDate;
@Entity @Table(name="transport_price_ranges") @SQLDelete(sql="UPDATE transport_price_ranges SET deleted=true, deleted_at=CURRENT_TIMESTAMP WHERE id=?") @SQLRestriction("deleted=false") @Getter @Setter @NoArgsConstructor @AllArgsConstructor @Builder
public class TransportPriceRange extends BaseEntity { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @ManyToOne(fetch=FetchType.LAZY) @JoinColumn(name="fuel_product_id") private FuelProduct fuelProduct; @Column(name="min_litres",nullable=false) private BigDecimal minLitres; @Column(name="max_litres",nullable=false) private BigDecimal maxLitres; @Column(name="transport_price",nullable=false) private BigDecimal transportPrice; @Column(name="effective_date",nullable=false) private LocalDate effectiveDate; @Builder.Default @Column(nullable=false) private String status="ACTIVE"; }
